export class Block {
  constructor() {
    this.free = true;
    this.value = "";
    this.symbol = "";
  }

  setValue(value) {
    this.value = value;

    if (this.value == "tick") {
      this.symbol = "done";
    } else {
      this.symbol = "close";
    }
  }

  urlimg() {
    return this.symbol == 'done' ? 'assets/bleu.jpg' : 'assets/gblanc.jpg';
  }

}
